Assume the usual includes.

struct Storage { int id; };
struct Reader : Storage { };
struct Writer : Storage { };
struct ReadWriter : Reader, Writer { void set() { id = 5; } };

What happens at the line id = 5;, and what is the standard remedy?

Assuming the usual includes and using namespace std, what does this program print?

struct B { virtual void f(int n = 1) { cout << "B" << n; } };
struct D : B { void f(int n = 2) override { cout << "D" << n; } };
int main() { B* p = new D; p->f(); }

Assuming the usual includes and using namespace std, what does this program print?

struct B { B() { speak(); } virtual void speak() { cout << "B"; } };
struct D : B { void speak() override { cout << "D"; } };
int main() { D d; }
